import { Pelayanan } from '@/services/bukti-pelranap'

interface Props {
  data: Pelayanan[]
  tindak_lanjut: string
  dokter: string
  pasien: string
}

function HeaderCol({ label }: { label: string }) {
  return (
    <th className='border border-black px-2 py-1 text-center text-[11px] font-medium whitespace-pre-line'>
      {label}
    </th>
  )
}

function SignatureCell({ label, image }: { label: string; image: string }) {
  return (
    <div className='border border-black flex-1 flex flex-col items-center justify-center p-2'>
      <img
        src={toImageUrl(image)}
        alt='ttd'
        className='w-[50px] h-[50px] object-contain'
      />
      <p className='text-xs text-center'>{label}</p>
    </div>
  )
}

export default function PelayananDirumahSakit({
  data,
  tindak_lanjut,
  dokter,
  pasien,
}: Props) {
  return (
    <div className='font-sans p-4 overflow-x-auto'>
      <p className='text-sm font-semibold mb-2 text-gray-900'>
        PELAYANAN DIRUMAH SAKIT
      </p>

      <table className='w-full min-w-[700px] text-[11px]'>
        <thead>
          <tr className='text-center'>
            <th
              rowSpan={3}
              className='border border-black px-2 py-1 text-center font-medium w-28'
            >
              Tanggal{'\n'}Pelayanan
            </th>
            <th
              colSpan={9}
              className='border border-black px-2 py-1 text-center font-medium'
            >
              PELAYANAN YANG DIBERIKAN
            </th>
            <th
              rowSpan={3}
              className='border border-black px-2 py-1 text-center font-medium w-16'
            >
              KET
            </th>
          </tr>
          <tr>
            {['Pemeriksaan', 'Penunj. Diagn.', 'Tindakan'].map((label) => (
              <th
                key={label}
                colSpan={3}
                className='border border-black px-2 py-1 text-center font-medium'
              >
                {label}
              </th>
            ))}
          </tr>
          <tr>
            {Array(3)
              .fill(['Jenis\nPelay.', 'Paraf\nDokter', 'Paraf\nPasien'])
              .flat()
              .map((label, i) => (
                <HeaderCol key={i} label={label} />
              ))}
          </tr>
        </thead>

        <tbody className='border border-black'>
          {data.map((row, i) => (
            <>
              <tr key={`r1-${i}`} className='text-center'>
                <td
                  rowSpan={4}
                  className='border border-black text-center text-lg font-semibold align-middle px-2'
                >
                  {row.tanggal}
                </td>
                <td>{row.pemeriksaan.jenis_pelayanan}</td>
                <td className='text-center items-center'>
                  <SignatureCell
                    image={row.pemeriksaan.paraf_dokter}
                    label={dokter}
                  />
                </td>
                <td>
                  <SignatureCell
                    image={row.pemeriksaan.paraf_pasien}
                    label={pasien}
                  />
                </td>

                <td>{row.penunjang_diagnosa.jenis_pelayanan}</td>
                <td>
                  <SignatureCell
                    image={row.penunjang_diagnosa.paraf_dokter}
                    label={dokter}
                  />
                </td>
                <td>
                  <SignatureCell
                    image={row.penunjang_diagnosa.paraf_pasien}
                    label={pasien}
                  />
                </td>

                <td>{row.tindakan.jenis_pelayanan}</td>
                <td>
                  <SignatureCell
                    image={row.tindakan.paraf_dokter}
                    label={dokter}
                  />
                </td>
                <td>
                  <SignatureCell
                    image={row.tindakan.paraf_pasien}
                    label={pasien}
                  />
                </td>
                <td>{row.keterangan}</td>
              </tr>
            </>
          ))}
        </tbody>
      </table>

      <p className='text-xs text-black mt-2'>
        Tindak Lanjut. : {tindak_lanjut}{' '}
      </p>
    </div>
  )
}

function toImageUrl(url: string) {
  const baseUrl = import.meta.env.VITE_BASE_API_URL_RME
  const image = baseUrl + '/app/images/bukti-pelranap/'
  return image + url
}
