import { Printer } from 'lucide-react'
import { z } from 'zod'

import { match } from 'ts-pattern'

import { createFileRoute } from '@tanstack/react-router'

import { Button } from '@/components/ui/button'
import ReportEwsAnak from '@/features/ews/index-anak'
import ReportEwsDewasa from '@/features/ews/index-dewasa'
import OperationReport from '@/features/laporan-operasi/components/operation-report'
import LembarSebabKematian from '@/features/pasien-pulang/rekam-medis/components/lembar-sebab-kematian'
import PemberianInformasi from '@/features/pasien-pulang/rekam-medis/components/pemberian-informasi'
import PenmedikLab from '@/features/pasien-pulang/rekam-medis/components/penmedik-laboratorium'
import PenmedikRadiologi from '@/features/pasien-pulang/rekam-medis/components/penmedik-radiologi'
import { CPPTResume } from '@/features/pasien-pulang/rekam-medis/components/report-cppt-resume'
import { CPPTSbarResume } from '@/features/pasien-pulang/rekam-medis/components/report-cppt-sbar-resume'
import RekamMedisGeneralConsentRanap from '@/features/pasien-pulang/rekam-medis/components/report-general-consent-ranap'
import ReportPersetujuanRawatGabung from '@/features/pasien-pulang/rekam-medis/components/report-persetujuan-rawat-gabung'
import RekamMedisGeneralConsent from '@/features/pasien-pulang/rekam-medis/components/report-rekam-medis'
import ReportResume from '@/features/pasien-pulang/rekam-medis/components/report-resume'
import ReportResumeRanap from '@/features/pasien-pulang/rekam-medis/components/report-resume-ranap'
import AsesmenAwalMedis from '@/features/pasien/asesmen-awal-medis'
import AsesmenAwalMedisPonek from '@/features/pasien/asesmen-awal-medis-ponek'
import { AsesmenKeperawatanBayi } from '@/features/pasien/asesmen-keperawatan-bayi'
import AsesmenAwalMedisRawatInap from '@/features/pasien/asesmen-medis-rawat-inap'
import { BuktiPelayananRanap } from '@/features/pasien/bukti-pelayanan-ranap'
import { CaseRegister } from '@/features/pasien/case-register'
import { AnalisaData } from '@/features/pasien/components/analisa-data'
import { AsesmenKeperawatanAnak } from '@/features/pasien/components/asesmen-keperawatan-anak'
import { AsesmenKeperawatanDewasa } from '@/features/pasien/components/asesmen-keperawatan-dewasa'
import { InstruksiMedisFarmakologi } from '@/features/pasien/components/instruksi-medis-farmakologi'
import { KontrolPasien } from '@/features/pasien/components/kontrol-pasien'
import { MonitoringCairan } from '@/features/pasien/components/monitoring-cairan'
import { ResikoJatuh } from '@/features/pasien/components/resiko-jatuh'
import { CPPT } from '@/features/pasien/cppt'
import { DaftarObatHarian } from '@/features/pasien/daftar-obat-harian'
import { EdukasiTerintegrasi } from '@/features/pasien/edukasi-terintegrasi'
import FormPengantarRawatInap from '@/features/pasien/form-pengantar-rawat-inap'
import GeneralConsent from '@/features/pasien/general-consent'
import LembaranKonsul from '@/features/pasien/lembaran-konsul'
import ReportTransfusiDarah from '@/features/pasien/monitoring-darah'
import Paps from '@/features/pasien/paps'
import PemilihanDPJP from '@/features/pasien/pemilihan-dpjp'
import PenundaanPelayanan from '@/features/pasien/penundaan_pelayanan'
import TindakanAnastesi from '@/features/pasien/tindakan_anastesi'
import PersetujuanTindakanKedokteran from '@/features/pasien/tindakan_kedokteran'
import TindakanPenolakan from '@/features/pasien/tindakan_penolakan'
import Triase from '@/features/pasien/triase'
import TriasePonek from '@/features/pasien/triase-ponek'

const searchSchema = z.object({
  no_rm: z.string().or(z.number()).optional(),
  noreg: z.string().or(z.number()).optional(),
  no: z.string().optional(),
})

export const Route = createFileRoute('/report/$report')({
  component: Report,
  validateSearch: searchSchema,
})

function Report() {
  const { report } = Route.useParams()
  const { noreg, no, no_rm } = Route.useSearch() as {
    noreg: string
    no: string
    no_rm: string
  }

  return (
    <div className='p-4 bg-white'>
      <Button
        onClick={() => {
          window.print()
        }}
        className='mb-4 w-full'
      >
        <Printer className='mr-2' /> Simpan Ke PDF
      </Button>
      {render(report.replace('_', '-'))}
    </div>
  )

  function render(report: string) {
    return match(report)
      .with('cppt', () => <CPPT isReport no_rm={no_rm} />)
      .with('asesmen-keperawatan-dewasa', () => <AsesmenKeperawatanDewasa />)
      .with('asesmen-keperawatan-anak', () => <AsesmenKeperawatanAnak />)
      .with('asesmen-keperawatan-bayi', () => <AsesmenKeperawatanBayi />)
      .with('resiko-jatuh', () => <ResikoJatuh />)
      .with('analisa-data', () => <AnalisaData />)
      .with('kontrol-pasien', () => <KontrolPasien />)
      .with('instruksi-medis-farmakologi', () => <InstruksiMedisFarmakologi />)
      .with('monitoring-cairan', () => <MonitoringCairan />)
      .with('general-consent', () => <GeneralConsent isReport />)
      .with('lembar-sebab-kematian-rekam-medis', () => (
        <LembarSebabKematian isReport noreg={noreg} />
      ))
      .with('general-consent-rekam-medis', () => (
        <RekamMedisGeneralConsent isReport noreg={noreg} no={no} />
      ))

      .with('pemberian-trasfusi-darah-rekam-medis', () => (
        <ReportTransfusiDarah isReport noreg={noreg} no={no} />
      ))

      .with('general-consent-rawat-inap-rekam-medis', () => (
        <RekamMedisGeneralConsent isReport noreg={noreg} no={no} />
      ))
      .with('general-consent-rawat-jalan-rekam-medis', () => (
        <RekamMedisGeneralConsentRanap isReport noreg={noreg} no={no} />
      ))
      .with('resume-rekam-medis', () => (
        <ReportResume isReport noreg={noreg} no={no} />
      ))
      .with('resume-rekam-medis-ranap', () => (
        <ReportResumeRanap isReport noreg={noreg} no={no} />
      ))
      .with('asesmen-awal-medis', () => <AsesmenAwalMedis isReport />)
      .with('asesmen-medis-rawat-inap-rekam-medis', () => (
        <AsesmenAwalMedisRawatInap noreg={noreg} isReport />
      ))
      .with('form-pengantar-rawat-inap-rekam-medis', () => (
        <FormPengantarRawatInap isReport noreg={noreg} no={no} />
      ))
      .with('asesmen-awal-medis-igd-rekam-medis', () => (
        <AsesmenAwalMedis isReport noreg={noreg} no={no} />
      ))
      .with('asesmen-awal-medis-ponek-rekam-medis', () => (
        <AsesmenAwalMedisPonek isReport noreg={noreg} no={no} />
      ))
      .with('daftar-obat-harian-rekam-medis', () => (
        <DaftarObatHarian noreg={noreg} />
      ))

      .with('ews-dewasa-rekam-medis', () => (
        <ReportEwsDewasa noreg={noreg} isReport norm={no_rm} />
      ))

      .with('ews-anak-rekam-medis', () => (
        <ReportEwsAnak noreg={noreg} isReport norm={no_rm} />
      ))

      .with('resume-rawat-inap-rekam-medis', () => (
        <ReportResumeRanap isReport noreg={noreg} />
      ))
      .with('triase-rekam-medis', () => (
        <Triase isReport noreg={noreg} no={no} />
      ))
      .with('triase-ponek-rekam-medis', () => (
        <TriasePonek isReport noreg={noreg} no={no} />
      ))
      .with('lembar-konsul-rekam-medis', () => (
        <LembaranKonsul isReport noreg={noreg} no={no} />
      ))
      .with('penundaan-pelayanan-rekam-medis', () => (
        <PenundaanPelayanan isReport noreg={noreg} no_rm={no_rm} />
      ))

      .with('tindakan-penolakan-kedokteran-rekam-medis', () => (
        <TindakanPenolakan isReport no_reg={noreg} no_rm={no_rm} bagian={''} />
      ))

      .with('formulir-paps-rekam-medis', () => (
        <Paps isReport noreg={noreg} no_rm={no_rm} />
      ))

      .with('edukasi-terintegrasi-rekam-medis', () => (
        <EdukasiTerintegrasi isReport={true} noreg={noreg} />
      ))

      .with('pemilihan-dpjp-rekam-medis', () => (
        <PemilihanDPJP isReport={true} noreg={noreg} no_rm={no_rm} />
      ))
      .with('tindakan-anastesi-rekam-medis', () => (
        <TindakanAnastesi isReport={true} noreg={noreg} no_rm={no_rm} />
      ))
      .with('persetujuan-tindakan-kedokteran-rekam-medis', () => (
        <PersetujuanTindakanKedokteran isReport={true} noreg={noreg} />
      ))
      .with('cppt-rekam-medis', () => (
        <CPPTResume isReport noreg={noreg} no={no} />
      ))
      .with('pelaksanaan-keperawatan', () => (
        <CPPTResume isReport noreg={noreg} no={no} />
      ))
      .with('sbar-rekam-medis', () => (
        <CPPTSbarResume isReport noreg={noreg} no={no} />
      ))

      .with('laporan-operasi-rekam-medis', () => (
        <OperationReport isReport noreg={noreg} />
      ))
      .with('laporan-operasi', () => <OperationReport isReport noreg={noreg} />)
      .with('persetujuan-rawat-gabung-rekam-medis', () => (
        <ReportPersetujuanRawatGabung isReport noreg={noreg} />
      ))
      .with('daftar-pemberian-obat-rekam-medis', () => (
        <DaftarObatHarian noreg={noreg} />
      ))

      .with('case-register-rekam-medis', () => (
        <CaseRegister noreg={noreg} isReport />
      ))

      .with('laboratorium-rekam-medis', () => (
        <PenmedikLab isReport noreg={noreg} />
      ))
      .with('radiologi-rekam-medis', () => (
        <PenmedikRadiologi isReport noreg={noreg} />
      ))
      .with('pemberian-informasi-rekam-medis', () => (
        <PemberianInformasi isReport noreg={noreg} />
      ))
      .with('bukti-pelayanan-rawat-inap-rekam-medis', () => (
        <BuktiPelayananRanap isReport noreg={noreg} />
      ))
      .otherwise(() => null)
  }
}
