import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { BuktiPelRanap, getBuktiPelRanap } from '@/services/bukti-pelranap'
import { constants } from '@/utils/constants'

import BuktiRawatInapComponent from './bukti-pelranap'

interface CaseRegisterProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function BuktiPelayananRanap({
  isReport = true,
  noreg = '',
  no = '',
}: CaseRegisterProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.buktiPelRanap, noreg],
    queryFn: () => getBuktiPelRanap({ no_reg: noreg }),
  })

  const result = data?.response != null ? data?.response : ({} as BuktiPelRanap)

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        {/* <h1 className='text-center text-black font-semibold mb-4'>
          BUKTI PELAYANAN RAWAT INAP
        </h1> */}

        <BuktiRawatInapComponent diagnosa={result.diagnosa} data={result} />

        <div>
          <div className='flex text-xs'></div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
