import { post } from '@/services/api-2'
import type {  Response } from '@/type'

export interface MonitoringTansfusiDarahModel {
  noreg: string
  jenis_darah : string
  no_kantung : string
  tgl_kadaluarsa : string
  gol_darah : string
  jam_pemberi : string
  reaksi : Reaksi[]
  perawat : Perawat
}

export interface Reaksi {
  reaksi : string
  keterangan : string
}


export interface Perawat {
  nama : string
}

const getMonitoringTransfusiDarah = async ({
  no_reg,
}: {
  no_reg: string
}): Promise<Response<MonitoringTansfusiDarahModel[]>> => {
  const response = await post(`v4/transfusi-darah/get`, {
    no_reg,
  })

  return response.data
}

export { getMonitoringTransfusiDarah }
