import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SignatureBox } from '@/components/signature'
import { getAllLaporanTindakanKedokteran } from '@/services/rekam-medis'
import { constants } from '@/utils/constants'

import EmtyPersetujuanTindakanKedokteran from './emty_data'

interface PersetujuanTindakanKedokteranProps {
  isReport?: boolean
  no?: string
  noreg?: string
}

export default function PersetujuanTindakanKedokteran({
  isReport = false,
  no = '',
  noreg = '',
}: PersetujuanTindakanKedokteranProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.persetujuanTindakanKedokteran,
      noreg,
    ],
    queryFn: () => getAllLaporanTindakanKedokteran(noreg || ''),
    enabled: !!noreg,
  })

  const res = data?.response != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />

  if (res == null) return <div>No data</div>

  if (res.length == 0)
    return (
      <EmtyPersetujuanTindakanKedokteran></EmtyPersetujuanTindakanKedokteran>
    )

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      {res.map((item, index) => (
        <div key={index} className='flex text-xs border-b border-black'>
          <div className='flex-1 border-black'>
            <div className='p-2'>
              <div className='max-w-4xl mx-auto text-center font-bold p-8 bg-white text-black font-sans leading-relaxed'>
                PERSETUJUAN TINDAKAN KEDOKTERAN
              </div>
              <div className='max-w-4xl mx-auto p-8 bg-white text-black font-sans leading-relaxed'></div>

              {/* // content here */}

              <div className='mb-6'>
                <p className='mb-4'>Yang bertanda tangan dibawah ini :</p>

                <p className='mb-6'>
                  Dengan ini menyatakan dengan sesungguhnya dari{' '}
                  <strong>TINDAKAN KEDOKTERAN</strong> dari :
                </p>

                <div className='grid grid-cols-[180px_10px_1fr] gap-y-2 mb-8'>
                  <span>Nama</span>
                  <span>:</span>
                  <span className='font-semibold'>
                    {item?.persetujuan.persetujuan_nama}
                  </span>
                  <span>Tanggal Lahir</span>
                  <span>:</span>
                  <span>{item?.persetujuan.persetujuan_tgllahir}</span>
                  <span>Alamat</span>
                  <span>:</span>
                  <span>{item?.persetujuan.persetujuan_alamat}</span>
                  <span>Jenis Kelamin</span>
                  <span>:</span>
                  <span>{item?.persetujuan.persetujuan_jeniskelamin}</span>
                </div>

                <p className='mb-4 text-justify'>
                  Dengan ini menyatakan <strong>* SETUJU *</strong> untuk
                  dilakukan tindakan medis <br />
                  <strong>{item?.persetujuan.berupa}</strong>
                </p>

                <p className='mb-12 text-justify'>
                  Dari penjelasan yang diberikan, saya telah mengerti segala hal
                  yang berhubungan dengan penyakit tersebut. Serta tindakan
                  medis yang akan dilakukan, dan kemungkinan pasca tindakan yang
                  dapat terjadi sesuai penjelasan yang diberikan.
                </p>
              </div>

              <div className='flex justify-between items-start mt-16'>
                <div className='text-center'>
                  <p>Dokter/Pelaksana</p>
                  <SignatureBox
                    signerName={item?.persetujuan.nama_dokter_pelaksana || ''}
                    imagePath={item?.persetujuan.ttd_dokter_pelaksana}
                  />
                </div>

                <div className='text-center'>
                  <p></p>
                  <p>Yang Membuat Pernyataan,</p>
                  <SignatureBox
                    signerName={item?.persetujuan.nama_membuat_pernyataan || ''}
                    imagePath={
                      `${import.meta.env.VITE_BASE_API_URL_RME}/app/images/tindakan_kedokteran/` +
                      item?.persetujuan.nama_membuat_pernyataan
                    }
                  />
                </div>
              </div>
            </div>
          </div>
        </div>
      ))}
    </LayoutBorderNo>
  )
}
