
import type {
  Response,
} from '@/type'
import { post } from './api-2'




const getBuktiPelRanap = async (
  { no_reg }: { no_reg: string }
): Promise<Response<BuktiPelRanap>> => {
  const response = await post(`/v1/bukti-pelranap/get`, {
    no_reg, // ⬅️ langsung pakai shorthand
  })

  console.log("Response API:", response.data) // cek di console
  return response.data
}



export {getBuktiPelRanap}




export interface BuktiPelRanap {
    id:             string;
    noreg:          string;
    rumah_sakit:    string;
    kelas:          string;
    nama_penderita: string;
    tanggal_lahir:  string;
    usia:           string;
    jenis_kelamin:  string;
    no_kartu_bpjs:  string;
    nama_peserta:   string;
    diagnosa:       Diagnosa[];
    pelayanan:      Pelayanan[];
    tindak_lanjut:  string;
    dokter:         string;
}

export interface Diagnosa {
    kode:      string;
    deskripsi: string;
}

export interface Pelayanan {
    no:                 number;
    tanggal:            string;
    pemeriksaan:        Pemeriksaan;
    penunjang_diagnosa: Pemeriksaan;
    tindakan:           Pemeriksaan;
    keterangan:         string;
}

export interface Pemeriksaan {
    jenis_pelayanan: string;
    paraf_dokter:    string;
    paraf_pasien:    string;
}

// Converts JSON strings to/from your types
export class Convert {
    public static toBuktiPelRanap(json: string): BuktiPelRanap {
        return JSON.parse(json);
    }

    public static buktiPelRanapToJson(value: BuktiPelRanap): string {
        return JSON.stringify(value);
    }
}
