import { PemberiInformasiModel } from '@/models/pemberian-informasi'
import { PersetujuanTindakanAnestesiModel } from '@/models/persetujuan-tindakan-anestesi-model'
import type { PersetujuanRawatGabung, Response } from '@/type'

import { post as p } from './api-2'

const getPemberiInformasi = async (
  no_reg: string,
): Promise<Response<PemberiInformasiModel>> => {
  const response = await p('/v1/pemberian-informasi/report', { no_reg })

  return response.data
}

const getAllPemberiInformasi = async (
  no_reg: string,
): Promise<Response<PemberiInformasiModel[]>> => {
  const response = await p('/v1/pemberian-informasi/report/all', { no_reg })

  return response.data
}

const getPersetujuanRawatGabung = async (
  noreg: string,
): Promise<Response<PersetujuanRawatGabung>> => {
  const response = await p('/v1/rawat-gabung/report', {
    noreg: noreg,
  })

  return response.data
}

const getPersetujuanTindakanKedokteran = async (
  noreg: string,
): Promise<Response<PersetujuanRawatGabung>> => {
  const response = await p('/v1/laporan-persetujuan-tindakan-kedokteran', {
    no_reg: noreg,
  })

  return response.data
}

const getPersetujuanTindakanAnestesi = async (
  noreg: string,
): Promise<Response<PersetujuanTindakanAnestesiModel>> => {
  const response = await p('/v1/tindakan-anasthesi/report', {
    no_reg: noreg,
  })

  return response.data
}

export {
  getPemberiInformasi,
  getPersetujuanRawatGabung,
  getPersetujuanTindakanKedokteran,
  getPersetujuanTindakanAnestesi,
  getAllPemberiInformasi,
}
