import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import Text from '@/components/text'
import { formatTanggalIndoV2 } from '@/helper/date'
import { constants } from '@/utils/constants'

import TableAsesmenNyeri from './components/table-asesmen-nyeri'
import { getTriasePONEK } from './triase'

interface TriasePonekProps {
  isReport?: boolean
  no?: string
  noreg?: string
}

export default function TriasePonek({
  isReport = false,
  no = '',
  noreg = '',
}: TriasePonekProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.triasePonek, noreg],
    queryFn: () => getTriasePONEK({ noreg }),
    enabled: !!noreg,
  })

  const res = data?.response != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />

  if (res == null) return

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      {/* Content */}
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-4'>TRIASE</h1>
        {/* Detail Kedatangan Pasien */}
        <div className='flex flex-col md:flex-row items-start md:items-center border border-black p-2 mb-1'>
          <div className='flex-1'>
            <Text
              kStyle='min-w-[150px]'
              k='Tanggal Masuk'
              v={formatTanggalIndoV2(res.tanggal)}
            />
          </div>
          <div className='flex-1'>
            <Text kStyle='min-w-[150px]' k='Jam Kedatangan' v={res.jam} />
          </div>
          <div className='flex-1'>
            <Text
              kStyle='min-w-[150px]'
              k='Jam Pemeriksaan'
              v={res.jam_pemeriksaan}
            />
          </div>
        </div>
        {/* Detail Kedatangan Pasien */}

        {/* Alasan Kedatangan */}
        <div className='border border-black p-2 mb-1'>
          <Text
            kStyle='font-semibold'
            k='Alasan Kedatangan'
            v={res.aseskep_asal_masuk}
          />
          <Text
            kStyle='font-semibold'
            k='Penyebab Cedera'
            v={res.penyebab_cedera}
          />
        </div>
        {/* Alasan Kedatangan */}

        {/* Keluhan Utama */}
        <div className='border border-black p-2 mb-1'>
          <Text kStyle='font-semibold' k='Keluhan Utama' v={res.keluhan} />
        </div>
        {/* Keluhan Utama */}

        {/* Tanda Vital */}
        <div className='border border-black p-2 mb-1'>
          <p className='text-xs font-semibold'>Tanda Vital</p>
          <div className='flex flex-col md:flex-row'>
            <div className='flex flex-1 items-center gap-2 p-2'>
              <div className='flex-1'>
                <div className='flex items-center gap-4'>
                  <p className='min-w-[150px] text-xs'>
                    GCS : E{res.gcs_e} V{res.gcs_v} M{res.gcs_m}
                  </p>
                </div>
                <Text kStyle='min-w-[150px]' k='TD' v={res.td} />
                <Text kStyle='min-w-[150px]' k='Nadi' v={res.nadi} />
              </div>
            </div>
            <div className='flex  flex-1 items-center gap-2 p-2'>
              <div className='flex-1'>
                <Text kStyle='min-w-[150px]' k='Pupil' v={res.pupil} />
                <Text
                  kStyle='min-w-[150px]'
                  k='Pernafasan'
                  v={res.pernafasan}
                />
                <Text kStyle='min-w-[150px]' k='Suhu' v={res.suhu} />
              </div>
            </div>
            <div className='flex  flex-1 items-center gap-2 p-2'>
              <div className='flex-1'>
                <Text
                  kStyle='min-w-[150px]'
                  k='Refleks Cahaya'
                  v={res.refleks}
                />
                <Text kStyle='min-w-[150px]' k='SpO2' v={res.spo2} />
                <Text kStyle='min-w-[150px]' k='Akral' v={res.akral} />
              </div>
            </div>
          </div>
        </div>
        {/* Tanda Vital */}

        <div className='border border-black p-2 mb-1'>
          <Text kStyle='font-semibold' k='Status Alergi' v={'status'} />
        </div>

        <div className='border border-black p-2 mb-1'>
          <Text kStyle='font-semibold' k='Gangguan Perilaku' v={''} />
        </div>

        <div className='border border-black p-2 mb-1'>
          <h1 className='text-lg font-normal'>
            Status Kehamilan (Khusus Obgyn)
          </h1>
          <Text
            kStyle='font-normal'
            k='Status Kehamilan (Khusus Obgyn)'
            v={res.hamil}
          />
          <Text kStyle='font-normal' k='Gravia' v={res.gravida} />
          <Text kStyle='font-normal' k='Para' v={res.para} />
          <Text kStyle='font-normal' k='Abortus ' v={res.abortus} />
          <Text kStyle='font-normal' k='HIS' v={res.his} />
          <Text kStyle='font-normal' k='HPHT' v={res.hpht} />
          <Text
            kStyle='font-normal'
            k='DJJ (Denyut Jantung Janin)'
            v={res.djj}
          />
        </div>

        {/* Asesmen Nyeri */}
        <div className='border border-black p-2 mb-1'>
          <p className='text-xs font-semibold mb-1'>Skala Triase </p>
          <TableAsesmenNyeri skalaTriase={res.skala_triase} />
        </div>
        {/* Asesmen Nyeri */}
      </div>
      {/* Content */}

      {/* Petugas Triase */}
      <div className='p-2 mb-1 m-2'>
        {res != null && res.nama != '' && (
          <div className='text-center flex flex-col items-center gap-2'>
            <p className='text-xs font-semibold'>Petugas Triase</p>
            <QRCode value={res.nama ?? ''} className='w-[100px] h-[100px]' />
            <p className='text-xs font-semibold'>({res.nama})</p>
          </div>
        )}
      </div>
      {/* Petugas Triase */}
    </LayoutBorderNo>
  )
}
