import type {  PapsModel, PemilihanDPJP, PenundaanPelayanan, Response, TindakanKedokteran, TindakanPenolakanModel } from '@/type'

import { post } from './api-2'
import { TindakanAnastesia } from '@/features/pasien/tindakan_anastesi/tindakan_anastesia_model'


const getTindakanKedokteran = async ({
  no_reg,
  no_rm,
}: {
    no_rm: string
    no_reg: string
}): Promise<Response<TindakanKedokteran>> => {   
    const response = await post(`/v1/report-penundaan-pelayanan`,{
        "no_rm": no_rm,
        "no_reg" : no_reg 
})
    
    return response.data
}


