import { formatTanggalIndo } from '@/helper/date'
import { BuktiPelRanap, Diagnosa } from '@/services/bukti-pelranap'

import PelayananDirumahSakit from './table-ranap'

interface RowProps {
  label: string
  value: string
}

function Row({ label, value }: RowProps) {
  return (
    <tr>
      <td className='text-gray-500 py-1.5 w-5/12 align-top text-sm'>{label}</td>
      <td className='text-gray-900 py-1.5 text-sm'>: {value}</td>
    </tr>
  )
}

function Divider() {
  return <hr className='border-t border-gray-200 my-3' />
}

// ✅ PERBAIKAN: type props ditulis di parameter, bukan setelah kurung kurawal
interface BuktiPelayananRanapProps {
  diagnosa: Diagnosa[]
  data: BuktiPelRanap
}

export default function BuktiRawatInapComponent({
  diagnosa,
  data,
}: BuktiPelayananRanapProps) {
  // ✅ bukan ): BuktiPelayananRanapProps
  return (
    <div className='px-5 py-6 bg-white font-sans text-gray-900'>
      {/* Header */}
      <div className='border-t-2 border-b y-3 text-center mb-6'>
        <h1 className='text-sm font-semibold tracking-widest'>
          BUKTI PELAYANAN RAWAT INAP
        </h1>
      </div>

      {/* Registrasi */}
      <table className='w-full'>
        <tbody>
          <Row label='No. Register' value={data.noreg} />
          <Row label='Rumah Sakit' value={data.rumah_sakit} />
          <Row label='Kelas Rumah Sakit' value={data.kelas} />
        </tbody>
      </table>

      <Divider />

      {/* Data Pasien */}
      <table className='w-full'>
        <tbody>
          <Row label='Nama Penderita' value={data.nama_penderita} />
          <Row
            label='Tanggal Lahir / Usia'
            value={
              formatTanggalIndo(data.tanggal_lahir) +
              ' / ' +
              data.usia +
              ' tahun'
            }
          />
          <Row label='Jenis Kelamin' value={data.jenis_kelamin} />
        </tbody>
      </table>

      <Divider />

      {/* BPJS */}
      <table className='w-full'>
        <tbody>
          <Row label='No. Kartu BPJS' value={data.no_kartu_bpjs} />
          <Row label='Nama Peserta' value={data.nama_peserta} />
        </tbody>
      </table>

      <Divider />

      {/* Diagnosa */}
      <p className='text-xs font-semibold text-gray-500 tracking-widest mb-3'>
        DIAGNOSA
      </p>

      <div className='flex flex-col gap-2'>
        {/* ✅ PERBAIKAN: pakai `diagnosa` dari props, bukan `data.diagnosa` */}
        {diagnosa.map((item: Diagnosa) => (
          <div
            key={item.kode}
            className='flex items-center gap-4 border border-gray-200 rounded-xl px-4 py-3'
          >
            <div className='bg-gray-100 border border-gray-200 rounded-lg px-3 py-1.5 min-w-[60px] text-center'>
              <span className='text-sm font-semibold text-gray-700'>
                {item.kode}
              </span>
            </div>
            <div>
              <p className='text-xs text-gray-400 mb-0.5'>Diagnosa</p>
              <p className='text-sm font-medium text-gray-900'>
                {item.deskripsi}
              </p>
            </div>
          </div>
        ))}
      </div>

      <PelayananDirumahSakit
        data={data.pelayanan}
        tindak_lanjut={data.tindak_lanjut}
        dokter={data.dokter}
        pasien={data.nama_peserta}
      />
    </div>
  )
}
