'use client'

import {
  CartesianGrid,
  LabelList,
  Line,
  LineChart,
  ResponsiveContainer,
  XAxis,
  YAxis,
} from 'recharts'

import { ChartContainer } from '@/components/ui/chart'

import { KontrolPasien } from '../ews-model'

export function Chart({
  data,
  title,
  stroke,
}: {
  data: KontrolPasien[]
  title: keyof KontrolPasien
  stroke?: string
}) {
  const chartMinWidth = Math.max(600, data.length * 90)
  return (
    <div className='overflow-x-auto'>
      <div
        className='flex h-[200px]'
        style={{ minWidth: chartMinWidth }}
      >
        <div className='border border-black w-[150px] h-[200px] flex flex-col items-center justify-center flex-shrink-0'>
          <h3 className='font-semibold uppercase text-xs'>{title}</h3>
        </div>
        <div className='h-[200px] flex-1 min-w-0'>
          <ChartContainer config={{}} className='h-full overflow-visible'>
            <ResponsiveContainer width='100%' height='100%'>
              <LineChart
                data={data}
                margin={{ top: 16, right: 16, left: 0, bottom: 16 }}
              >
                <CartesianGrid vertical={false} />
                <XAxis
                  padding={{ left: 16, right: 16 }}
                  dataKey='waktu'
                  tickLine={false}
                  tickMargin={10}
                  axisLine={false}
                  tickFormatter={(value: string | number) => String(value)}
                />
                <YAxis dataKey={title} />
                <Line
                  type='monotone'
                  dataKey={title}
                  strokeWidth={1.5}
                  stroke={stroke}
                >
                  <LabelList dataKey={title} position='top' />
                </Line>
              </LineChart>
            </ResponsiveContainer>
          </ChartContainer>
        </div>
      </div>
    </div>
  )
}
