import { Printer, Sidebar } from 'lucide-react'

import { useState } from 'react'
import { match } from 'ts-pattern'

import { DialogDescription, DialogTitle } from '@radix-ui/react-dialog'
import { Link } from '@tanstack/react-router'

import { images } from '@/assets/images/images'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Button } from '@/components/ui/button'
import { Dialog, DialogContent } from '@/components/ui/dialog'
import LaporanOperasi from '@/features/laporan-operasi'
import PemberianInformasi from '@/features/pasien-pulang/rekam-medis/components/pemberian-informasi'
import PenmedikLab from '@/features/pasien-pulang/rekam-medis/components/penmedik-laboratorium'
import PenmedikRadiologi from '@/features/pasien-pulang/rekam-medis/components/penmedik-radiologi'
import RekamMedisGeneralConsentRanap from '@/features/pasien-pulang/rekam-medis/components/report-general-consent-ranap'
import ReportResume from '@/features/pasien-pulang/rekam-medis/components/report-resume'
import { useAuthStore } from '@/store/auth.store'
import { useGlobalStore } from '@/store/global.store'
import { usePasienStore } from '@/store/pasien.store'
import { Pasien } from '@/type'
import { constants } from '@/utils/constants'

import { AsesmenKeperawatanBayi } from '../asesmen-keperawatan-bayi'
import AsesmenAwalMedisRawatInap from '../asesmen-medis-rawat-inap'
import { BuktiPelayananRanap } from '../bukti-pelayanan-ranap'
import { CaseRegister } from '../case-register'
import { CPPT } from '../cppt'
import { DaftarObatHarian } from '../daftar-obat-harian'
import { EdukasiTerintegrasi } from '../edukasi-terintegrasi'
import FormPengantarRawatInap from '../form-pengantar-rawat-inap'
import GeneralConsent from '../general-consent'
import LembaranKonsul from '../lembaran-konsul'
import ReportTransfusiDarah from '../monitoring-darah'
import Paps from '../paps'
import PelaksanaanKeperawatan from '../pelaksanaan_keperawatan'
import PemilihanDPJP from '../pemilihan-dpjp'
import PenundaanPelayanan from '../penundaan_pelayanan'
import PersetujuanRawatGabung from '../persetujuan_rawat_gabung'
import { SBARReport } from '../sbar'
import TindakanAnastesi from '../tindakan_anastesi'
import PersetujuanTindakanKedokteran from '../tindakan_kedokteran'
import TindakanPenolakan from '../tindakan_penolakan'
import Triase from '../triase'
import TriasePonek from '../triase-ponek'
import { AnalisaData } from './analisa-data'
import { AsesmenKeperawatanAnak } from './asesmen-keperawatan-anak'
import { AsesmenKeperawatanDewasa } from './asesmen-keperawatan-dewasa'
import { InstruksiMedisFarmakologi } from './instruksi-medis-farmakologi'
import { KontrolPasien } from './kontrol-pasien'
import { MonitoringCairan } from './monitoring-cairan'
import { ResikoJatuh } from './resiko-jatuh'

export function DetailPasien() {
  // store
  const { user } = useAuthStore((state) => state)
  const { pasien } = usePasienStore((state) => state)
  const { dialogId, setDialogId } = useGlobalStore((state) => state)

  // state
  const [showSideBar, setShowSideBar] = useState(true)

  // selected menu
  const [menu] = useState<Menu[]>(initalMenu)
  const [selectedMenu, setSelectedMenu] = useState<Menu>(Menu.CPPT)

  const to = selectedMenu.replace(/\s+/g, '-').toLowerCase()

  return (
    <>
      <Dialog
        modal
        open={dialogId == 'dialog-detail-pasien'}
        onOpenChange={() => {
          setSelectedMenu(Menu.CPPT)
          setDialogId('')
        }}
      >
        <DialogTitle></DialogTitle>
        <DialogDescription></DialogDescription>
        <DialogContent className='min-h-screen max-w-screen-2xl '>
          <div className='flex'>
            {/* Left Content */}
            {showSideBar && (
              <div className='w-[250px] border p-4 flex flex-col h-[calc(100vh-32px)]'>
                {/* Profile Pasien */}
                <div className='h-[200px] border flex flex-col justify-center items-center text-center'>
                  <Avatar className='h-[100px] w-[100px]'>
                    <AvatarImage
                      src={
                        pasien?.jenis_kelamin == 'Laki-Laki'
                          ? images.man
                          : images.woman
                      }
                      alt='pasien photos'
                    />
                    <AvatarFallback className='text-2xl'>
                      {/* {pasien?.nama_pasien[0]} */}
                    </AvatarFallback>
                  </Avatar>
                  <h3 className='text-sm mt-4'>{pasien?.nama_pasien}</h3>
                  <p className='text-xs'>{pasien?.no_rm}</p>
                  <p className='text-xs'>{pasien?.no_reg}</p>
                  <p className='text-xs'>{constants.version}</p>
                </div>
                {/* Profile Pasien */}
                <div className='flex-1 mt-4 overflow-y-auto'>
                  <div className='w-full p-2'>
                    {Object.values(menu).map((item, i) => (
                      <Button
                        variant={selectedMenu != item ? 'outline' : 'default'}
                        className='w-full mb-2 hover:translate-x-1 transition-all ease-in-out text-[10px] font-semibold'
                        key={i}
                        onClick={() => {
                          setSelectedMenu(item)
                        }}
                      >
                        {item}
                      </Button>
                    ))}
                  </div>
                </div>
              </div>
            )}
            {/* Left Content */}
            {/* Right Content */}
            <div className='w-full'>
              {/* AppBar */}
              <div className='h-[50px] px-2 w-full bg-primaryColor flex items-center justify-between'>
                <div className='flex items-center gap-2'>
                  <Sidebar
                    className='text-white hover:cursor-pointer'
                    onClick={() => setShowSideBar((prev) => !prev)}
                  />
                  <h3 className='text-lg font-medium text-white'>
                    {selectedMenu == 'CPPT'
                      ? 'CATATAN PERKEMBANGAN PASIEN TERINTEGRASI'
                      : selectedMenu}
                  </h3>
                </div>
                <Link
                  to={`/report/${to}-rekam-medis?noreg=${pasien?.no_reg}`}
                  target='_blank'
                >
                  <Printer className='text-white mr-10 hover:cursor-pointer' />
                </Link>{' '}
              </div>
              {/* AppBar */}
              <div className='w-full border h-[calc(100vh-32px)] overflow-y-scroll'>
                <div className='p-2'>{render(selectedMenu, pasien!)}</div>
              </div>
            </div>
            {/* FAB */}
            <FAB />
            {/* FAB */}
          </div>
        </DialogContent>
      </Dialog>
    </>
  )

  function FAB() {
    let show = true

    if (
      pasien?.bagian !== user?.bagian ||
      selectedMenu === Menu.GENERAL_CONSENT_RAWAT_JALAN ||
      selectedMenu === Menu.TRIASE
    ) {
      show = false
    }

    return <div className='relative'>{show && <div></div>}</div>
  }
}

enum Menu {
  GENERAL_CONSENT_RAWAT_JALAN = 'GENERAL CONSENT RAWAT JALAN',
  GENERAL_CONSENT_RAWAT_INAP = 'GENERAL CONSENT RAWAT INAP',
  RESUME_RAWAT_INAP = 'RESUME MEDIS',
  TRIASE = 'TRIASE',
  LEMBAR_KONSUL = 'LEMBAR KONSUL',
  CPPT = 'CPPT',
  FORM_PENGANTAR_RAWAT_INAP = 'FORM PENGANTAR RAWAT INAP',
  SBAR = 'SBAR',
  PELAKSANAAN_KEPERAWATAN = 'PELAKSANAAN KEPERAWATAN',
  ASESMEN_MEDIS_RAWAT_INAP = 'ASESMEN MEDIS RAWAT INAP',
  ASESMEN_MEDIS_PONEK = 'ASESMEN MEDIS RAWAT PONEK',
  TRIASE_PONEK = 'TRIASE PONEK',
  PEMILIHAN_DPJP = 'PEMILIHAN DPJP',
  TINDAKAN_PENOLAKAN_KEDOKTERAN = 'TINDAKAN PENOLAKAN KEDOKTERAN',
  PENUNDAAN_PELAYANAN = 'PENUNDAAN PELAYANAN',
  PAPS = 'PAPS',
  PERSETUJUAN_TINDAKAN_KEDOKTERAN = 'PERSETUJUAN TINDAKAN KEDOKTERAN',
  TINDAKAN_ANESTESI = 'TINDAKAN ANESTESI',
  PERSETUJUAN_RAWAT_GABUNG = 'PERSETUJUAN RAWAT GABUNG',
  LABORATORIUM = 'LABORATORIUM',
  RADIOLOAGI = 'RADIOLOAGI',
  PEMBERI_INFORMASI = 'PEMBERI INFORMASI',
  DAFTAR_PEMBERIAN_OBAT = 'DAFTAR PEMBERIAN OBAT',
  CASE_REGISTER = 'CASE REGISTER',
  LAPORAN_OPERASI = 'LAPORAN OPERASI',
  PEMBERIAN_TRANSFUSI_DARAH = 'PEMBERIAN TRANSFUSI DARAH',
  BUKTI_PELAYANAN_RAWAT_INAP = 'BUKTI PELAYANAN RAWAT INAP',
  EDUKASI_TERINTEGRASI = 'EDUKASI TERINTEGRASI',
  ASESMEN_KEPERAWATAN_DEWASA = 'ASESMEN KEPERAWATAN DEWASA',
  ASESMEN_KEPERAWATAN_ANAK = 'ASESMEN KEPERAWATAN ANAK',
  ASESMEN_KEPERAWATAN_BAYI = 'ASESMEN KEPERAWATAN BAYI',
  RESIKO_JATUH = 'RESIKO JATUH',
  ANALISA_DATA = 'ANALISA DATA',
  KONTROL_PASIEN = 'KONTROL PASIEN',
  INSTRUKSI_MEDIS_FARMAKOLOGI = 'INSTRUKSI MEDIS FARMAKOLOGI',
  MONITORING_CAIRAN = 'MONITORING CAIRAN',
}

const initalMenu = [
  Menu.GENERAL_CONSENT_RAWAT_JALAN,
  Menu.GENERAL_CONSENT_RAWAT_INAP,
  Menu.TRIASE,
  Menu.LEMBAR_KONSUL,
  Menu.CPPT,
  Menu.FORM_PENGANTAR_RAWAT_INAP,
  Menu.SBAR,
  Menu.PELAKSANAAN_KEPERAWATAN,
  Menu.ASESMEN_MEDIS_RAWAT_INAP,
  Menu.ASESMEN_MEDIS_PONEK,
  Menu.TRIASE_PONEK,
  Menu.PEMILIHAN_DPJP,
  Menu.TINDAKAN_PENOLAKAN_KEDOKTERAN,
  Menu.PENUNDAAN_PELAYANAN,
  Menu.PAPS,
  Menu.PERSETUJUAN_TINDAKAN_KEDOKTERAN,
  Menu.TINDAKAN_ANESTESI,
  Menu.PERSETUJUAN_RAWAT_GABUNG,
  Menu.LABORATORIUM,
  Menu.RADIOLOAGI,
  Menu.PEMBERI_INFORMASI,
  Menu.DAFTAR_PEMBERIAN_OBAT,
  Menu.CASE_REGISTER,
  Menu.LAPORAN_OPERASI,
  Menu.PEMBERIAN_TRANSFUSI_DARAH,
  Menu.BUKTI_PELAYANAN_RAWAT_INAP,
  Menu.EDUKASI_TERINTEGRASI,
  Menu.ASESMEN_KEPERAWATAN_DEWASA,
  Menu.ASESMEN_KEPERAWATAN_ANAK,
  Menu.ASESMEN_KEPERAWATAN_BAYI,
  Menu.RESIKO_JATUH,
  Menu.ANALISA_DATA,
  Menu.KONTROL_PASIEN,
  Menu.INSTRUKSI_MEDIS_FARMAKOLOGI,
  Menu.MONITORING_CAIRAN,
  Menu.GENERAL_CONSENT_RAWAT_INAP,
]

function render(menu: Menu, pasien: Pasien) {
  return match(menu)
    .with(Menu.CPPT, () => <CPPT />)
    .with(Menu.PELAKSANAAN_KEPERAWATAN, () => (
      <PelaksanaanKeperawatan
        isReport={false}
        no=''
        noreg={pasien.no_reg}
        no_rm={pasien.no_rm}
      />
    ))

    .with(Menu.GENERAL_CONSENT_RAWAT_JALAN, () => <GeneralConsent />)
    .with(Menu.ASESMEN_KEPERAWATAN_DEWASA, () => <AsesmenKeperawatanDewasa />)
    .with(Menu.ASESMEN_KEPERAWATAN_ANAK, () => <AsesmenKeperawatanAnak />)
    .with(Menu.ASESMEN_KEPERAWATAN_BAYI, () => <AsesmenKeperawatanBayi />)
    .with(Menu.RESIKO_JATUH, () => <ResikoJatuh />)
    .with(Menu.ANALISA_DATA, () => <AnalisaData />)
    .with(Menu.KONTROL_PASIEN, () => <KontrolPasien />)
    .with(Menu.INSTRUKSI_MEDIS_FARMAKOLOGI, () => <InstruksiMedisFarmakologi />)
    .with(Menu.MONITORING_CAIRAN, () => <MonitoringCairan />)
    .with(Menu.EDUKASI_TERINTEGRASI, () => (
      <EdukasiTerintegrasi noreg={pasien.no_reg} />
    ))
    .with(Menu.TRIASE_PONEK, () => (
      <TriasePonek noreg={pasien.no_reg} isReport />
    ))
    .with(Menu.GENERAL_CONSENT_RAWAT_INAP, () => (
      <RekamMedisGeneralConsentRanap />
    ))
    .with(Menu.ASESMEN_MEDIS_RAWAT_INAP, () => (
      <AsesmenAwalMedisRawatInap isReport noreg={pasien.no_reg} no='' />
    ))
    .with(Menu.FORM_PENGANTAR_RAWAT_INAP, () => (
      <FormPengantarRawatInap isReport noreg={pasien.no_reg} no='' />
    ))

    .with(Menu.PENUNDAAN_PELAYANAN, () => (
      <PenundaanPelayanan isReport noreg={pasien.no_reg} no_rm={pasien.no_rm} />
    ))
    .with(Menu.PERSETUJUAN_TINDAKAN_KEDOKTERAN, () => (
      <PersetujuanTindakanKedokteran isReport noreg={pasien.no_reg} />
    ))
    .with(Menu.PEMBERIAN_TRANSFUSI_DARAH, () => (
      <ReportTransfusiDarah
        isReport
        noreg={pasien.no_reg}
        norm={pasien.no_rm}
      />
    ))
    .with(Menu.BUKTI_PELAYANAN_RAWAT_INAP, () => (
      <BuktiPelayananRanap isReport noreg={pasien.no_reg} />
    ))
    .with(Menu.SBAR, () => (
      <SBARReport no_reg={pasien.no_reg} isReport={false} />
    ))
    .with(Menu.RESUME_RAWAT_INAP, () => (
      <ReportResume noreg={pasien.no_reg} isReport={false} />
    ))
    .with(Menu.LEMBAR_KONSUL, () => (
      <LembaranKonsul noreg={pasien.no_reg} isReport={false} />
    ))
    .with(Menu.PEMILIHAN_DPJP, () => (
      <PemilihanDPJP
        noreg={pasien.no_reg}
        isReport={false}
        no_rm={pasien.no_rm}
      />
    ))

    .with(Menu.PAPS, () => (
      <Paps noreg={pasien.no_reg} isReport={false} no_rm={pasien.no_rm} />
    ))
    .with(Menu.TINDAKAN_PENOLAKAN_KEDOKTERAN, () => (
      <TindakanPenolakan
        no_reg={pasien.no_reg}
        bagian=''
        no_rm={pasien.no_rm}
        isReport={false}
      />
    ))
    .with(Menu.TINDAKAN_ANESTESI, () => (
      <TindakanAnastesi
        noreg={pasien.no_reg}
        no_rm={pasien.no_rm}
        isReport={false}
      />
    ))

    .with(Menu.LABORATORIUM, () => (
      <PenmedikLab noreg={pasien.no_reg} isReport={false} />
    ))

    .with(Menu.RADIOLOAGI, () => (
      <PenmedikRadiologi noreg={pasien.no_reg} isReport={false} />
    ))

    .with(Menu.PEMBERI_INFORMASI, () => (
      <PemberianInformasi noreg={pasien.no_reg} isReport={false} />
    ))

    .with(Menu.DAFTAR_PEMBERIAN_OBAT, () => (
      <DaftarObatHarian noreg={pasien.no_reg} isReport={false} />
    ))

    .with(Menu.CASE_REGISTER, () => (
      <CaseRegister noreg={pasien.no_reg} isReport={false} />
    ))

    .with(Menu.LAPORAN_OPERASI, () => <LaporanOperasi />)

    .with(Menu.PERSETUJUAN_RAWAT_GABUNG, () => (
      <PersetujuanRawatGabung noreg={pasien.no_reg} isReport={false} />
    ))
    .with(Menu.TRIASE, () => <Triase noreg={pasien.no_reg} />)
    .otherwise(() => null)
}
