'use client'

import * as React from 'react'

interface ChartContainerProps {
  config?: Record<string, unknown>
  className?: string
  children: React.ReactNode
}

export function ChartContainer({
  config,
  className,
  children,
}: ChartContainerProps) {
  return (
    <div
      className={className}
      data-config={JSON.stringify(config)}
    >
      {children}
    </div>
  )
}

interface ChartTooltipProps {
  active?: boolean
  payload?: Array<{
    value: number
    name: string
    color: string
  }>
  label?: string
}

export function ChartTooltip({
  active,
  payload,
  label,
}: ChartTooltipProps) {
  if (!active || !payload) {
    return null
  }

  return (
    <div
      className="bg-background border border-border rounded-lg shadow-lg p-3"
      style={{
        backgroundColor: 'hsl(var(--background))',
        borderColor: 'hsl(var(--border))',
      }}
    >
      <p className="font-medium text-foreground">{label}</p>
      {payload.map((entry, index) => (
        <p
          key={index}
          className="text-sm text-foreground"
          style={{ color: entry.color }}
        >
          {entry.name}: {entry.value}
        </p>
      ))}
    </div>
  )
}

interface ChartLegendProps {
  payload?: Array<{
    value: string
    color: string
  }>
}

export function ChartLegend({ payload }: ChartLegendProps) {
  if (!payload) {
    return null
  }

  return (
    <div className="flex flex-wrap gap-4">
      {payload.map((entry, index) => (
        <div
          key={index}
          className="flex items-center gap-2 text-sm"
        >
          <div
            className="h-3 w-3 rounded"
            style={{ backgroundColor: entry.color }}
          />
          <span className="text-foreground">{entry.value}</span>
        </div>
      ))}
    </div>
  )
}

interface ChartTooltipContentProps {
  active?: boolean
  payload?: Array<{
    value: number
    name: string
    color: string
  }>
  label?: string
}

export function ChartTooltipContent({
  active,
  payload,
  label,
}: ChartTooltipContentProps) {
  if (!active || !payload) {
    return null
  }

  return (
    <div className="grid gap-2 p-3 bg-background border border-border rounded-lg shadow-lg">
      <p className="font-medium text-foreground">{label}</p>
      {payload.map((entry, index) => (
        <div
          key={index}
          className="flex items-center gap-2 text-sm"
          style={{ color: entry.color }}
        >
          <span>{entry.name}:</span>
          <span className="font-medium">{entry.value}</span>
        </div>
      ))}
    </div>
  )
}