// import QRCode from 'react-qr-code'
import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { getResumeMedisV2 } from '@/services/rekam-medis'
import { constants } from '@/utils/constants'

import { DiagnosaTable } from './diagnosa-table'
import { LaborTableV2 } from './labor-tablev2'
import { TextField } from './text-field'
import { TextTitle } from './text-title'
import { TindakanTable } from './tindakan-table'

interface ReportResumeProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportResume({
  isReport = false,
  noreg = '',
  no,
}: ReportResumeProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.resumeMedis, noreg],
    queryFn: () => getResumeMedisV2(noreg),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo isReport={isReport} no={no}>
      <div className='p-4'>
        <h3 className='font-bold text-center py-3'>
          RINGKASAN PERAWATAN PASIEN PULANG / RESUME
        </h3>

        <div className='flex items-center gap-4 border p-2 mb-4'>
          <div className='flex-1'>
            <TextField title='Nama' value={res?.nama_pasien} />
            <TextField title='Tanggal Lahir' value={res?.tanggal_lahir} />
            <TextField title='Nomor Rekam Medis' value={res?.no_rm} />
            <TextField title='Tanggal Masuk' value={res?.tgl_masuk} />
            <TextField title='Tanggal Keluar' value={res?.tgl_keluar} />
          </div>
          <div className='flex-1'>
            <TextField title='No. Register' value={res?.no_register} />
            <TextField title='Jenis Kelamin' value={res?.jenis_kelamin} />
            <TextField title='Alamat' value={res?.alamat} />
            <TextField
              title='Ruangan/Kelas'
              value={`${res?.ruang}/${res?.kelas}`}
            />
            <TextField
              title='Dokter Merawat'
              value={res?.dokter_merawat?.map((d) => d.nama_dokter).join('\n')}
            />
          </div>
        </div>

        <div className='flex items-center gap-4 border p-2 mb-4'>
          <div className='flex-1'>
            <TextTitle title='Riwayat Penyakit' />
            <p className='text-xs'>{res?.riwayat_penyakit}</p>
            <div>
              <TextTitle title='Pemeriksaan Fisik' />
              <div className='flex items-start  gap-4'>
                <div className='flex-1'>
                  <TextField title='TB' value={res?.pemeriksaan_fisik?.tb} />
                  <TextField title='TD' value={res?.pemeriksaan_fisik?.td} />
                  <TextField title='BB' value={res?.pemeriksaan_fisik?.bb} />
                  <TextField
                    title='Nadi'
                    value={res?.pemeriksaan_fisik?.nadi}
                  />
                </div>
                <div className='flex-1'>
                  <TextField
                    title='Suhu'
                    value={res?.pemeriksaan_fisik?.suhu}
                  />
                  <TextField
                    title='Spo2'
                    value={res?.pemeriksaan_fisik?.spo2}
                  />
                  <TextField
                    title='Pernafasan'
                    value={res?.pemeriksaan_fisik?.penafasan}
                  />
                </div>
              </div>
            </div>

            <div className='border p-2 mb-4 mt-4'>
              <TextTitle title='Diagnosa Masuk' />
              <DiagnosaTable data={res != null ? res.diagnosa_masuk : []} />
            </div>

            <div className='border p-2 mb-4'>
              <TextTitle title='Diagnosa Akhir' />
              <DiagnosaTable data={res != null ? res.diagnosa_utama : []} />
            </div>

            {/* <div className='border p-2 mb-4'>
              <TextTitle title='Diagnosa Lainnya' />
              <DiagnosaTable data={res != null ? res.diagnosa_lain : []} />
            </div> */}

            <div className='border p-2 mb-4'>
              <TextTitle title='Tindakan Sesuai ICD-9' />
              <TindakanTable data={res != null ? res.tindakan : []} />
            </div>

            <div className='border p-2 mb-4'>
              <TextTitle title='Pemeriksaan Penunjang' />
              <TextTitle title='Laboratorium' />
              <LaborTableV2 data={res != null ? res.laboratorium : []} />
            </div>

            <div className='border p-2 mb-4'>
              <TextTitle title='Radiologi' />
              <LaborTableV2 data={res != null ? res.radio : []} />
            </div>

            <div className='border p-2 mb-4'>
              <TextTitle title='Lainnya' />
              <LaborTableV2 data={res != null ? res.lainnya : []} />
            </div>

            {/* <div>
              <TextTitle
                title={`Pemberian Medika mentosa & Obat waktu pulang`}
              />
              <ObatTable data={res != null ? res.obat_keluar : []} />
            </div> */}

            <div className='border p-2 mb-4 '>
              <TextTitle title='Terapi yang sudah diberi' />
              <div className='w-full flex-1 border border-gray-300 rounded px-2 py-1 resize-none whitespace-pre-wrap'>
                <TextTitle title={`${res?.terapi_diberi}`} />
              </div>
            </div>

            <div className='border p-2 mb-4 '>
              <TextTitle title='Alergi Obat' />
              <div className='w-full flex-1 border border-gray-300 rounded px-2 py-1 resize-none whitespace-pre-wrap'>
                <TextTitle title={`${res?.alergi_obat}`} />
              </div>
            </div>

            <div className='mt-4'>
              <TextField title='Cara keluar RS' value={res?.keadaan_pulang} />
              <TextField title='Kondisi Pasien' value={res?.kondisi_pulang} />
              <TextField title='Kontrol Ulang' value={res?.kontrol} />
              <TextField title='Tanggal/Jam' value={res?.tanggal_kontrol} />
            </div>

            <div className='mt-5'>
              <TextField title='Instruksi Pelayanan' value='' />
              <TextField
                title='Kesehatan yang diperlukan pasien'
                value={res?.instruksi_pelayanan}
              />
            </div>
          </div>
        </div>

        {/* Tanda Tangan */}
        <div className='ml-4'>
          <div className='py-10' />
          <div className='flex items-end justify-between'>
            <div className='w-full text-center flex flex-col justify-between items-center gap-4'>
              {res != null && res.nama_pasien != '' ? (
                <>
                  <p className='text-sm font-medium'>Pasien / Keluarga</p>
                  {res.nama_pasien != null ? (
                    <SimpleColumn
                      hasQR
                      height='h-[100px] w-[100px]'
                      name={'( ' + res.nama_pasien.toUpperCase() + ')'}
                      className='flex-1 border border-white text-center'
                      className2='text-xs'
                    />
                  ) : (
                    <div className='h-[100px]' />
                  )}
                </>
              ) : (
                <div className='h-[100px]' />
              )}
            </div>
            <div className='w-full text-center items-center flex flex-col gap-4'>
              {res != null && res?.dokter_merawat ? (
                <>
                  <p className='text-sm font-medium'>Dokter Yang Merawat</p>
                  {res.dokter_merawat != null ? (
                    <div className='flex'>
                      {res.dokter_merawat.map((item) => (
                        <SimpleColumn
                          hasQR
                          height='h-[100px] w-[100px]'
                          name={'( ' + item.nama_dokter.toUpperCase() + ')'}
                          className='flex-1 border border-white text-center'
                          className2='text-xs'
                        />
                      ))}
                    </div>
                  ) : (
                    <div className='h-[100px]' />
                  )}
                </>
              ) : (
                <div className='h-[100px]' />
              )}
            </div>
          </div>
        </div>
        {/* Tanda Tangan */}
      </div>
    </LayoutBorderNo>
  )
}
