import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report_header'
import { cn } from '@/lib/utils'
import { constants } from '@/utils/constants'

import { Chart } from './components/chart'
import { TekananDarahChart } from './components/tekanan-darah-chart'
import { getEwsDewasa, initEWS } from './ews'

interface ReportEwsProps {
  isReport?: boolean
  noreg?: string
  norm?: string
  no?: string
  kdBag?: string
}

const ReportEwsDewasa = ({ isReport, noreg, norm }: ReportEwsProps) => {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.ewsDewasa, noreg],
    queryFn: () => getEwsDewasa({ noRM: norm!, noReg: noreg! }),
    enabled: !!noreg,
  })

  const res = data?.response != null ? data.response : initEWS

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.kontrol_pasien.length == 0)
    return <EmptyPlaceholder message={'data kosong'} />
  return (
    <LayoutBorderNo>
      {isReport && <ReportHeader />}

      <div className='p-4'>
        <h1 className='text-center text-black font-bold text-lg mb-6'>
          EARLY WARNING SYSTEM DEWASA
        </h1>

        {/* Charts Section */}
        <div className='overflow-x-auto mb-6'>
          <div className='w-full min-w-0'>
            <TekananDarahChart data={res.kontrol_pasien} />
            <Chart title='nadi' data={res.kontrol_pasien} stroke='red' />
            <Chart
              title='pernapasan'
              data={res.kontrol_pasien}
              stroke='lightblue'
            />
            <Chart title='suhu' data={res.kontrol_pasien} stroke='green' />
          </div>
        </div>

        {isReport && (
          <div className='space-y-6'>
            {/* EWS Score Table */}
            <div className='overflow-x-auto'>
              <div className='flex min-w-max'>
                <div className='h-[50px] w-[165px] flex-shrink-0'>
                  <div className='p-2 border border-black border-b-0'>
                    <p className='text-xs text-center font-medium'>Tanggal</p>
                  </div>
                  <div className='p-2 border border-black border-b-0'>
                    <p className='text-xs text-center font-medium'>Total EWS</p>
                  </div>
                  <div className='p-2 border border-black'>
                    <p className='text-xs text-center font-medium'>
                      Keterangan
                    </p>
                  </div>
                </div>
                <div className='flex min-w-max'>
                  {res.kontrol_pasien.map((item) => (
                    <div
                      key={`${item.waktu}-${item.skor_ews}`}
                      className='w-[115px] flex-shrink-0'
                    >
                      <div className='p-2 border border-black border-b-0 border-l-0'>
                        <p className='text-[10px] text-center font-medium whitespace-normal break-words leading-4'>
                          {item.waktu}
                        </p>
                      </div>
                      <div className='p-2 border border-black border-b-0 border-l-0'>
                        <p className='text-xs text-center font-medium'>
                          {item.skor_ews}
                        </p>
                      </div>
                      <div
                        className={cn(
                          'p-2 border border-black border-l-0',
                          item.keterangan_ews.includes('RISIKO RINGAN')
                            ? 'bg-green-500'
                            : item.keterangan_ews.includes('RISIKO SEDANG')
                              ? 'bg-yellow-400'
                              : 'bg-red-500'
                        )}
                      >
                        <p className='text-xs text-center font-medium text-white whitespace-normal break-words leading-4'>
                          {item.keterangan_ews}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Pain Score Table */}
            <div className='flex'>
              <div className='w-[200px] flex-shrink-0'>
                <div className='h-[100px] p-2 border border-black border-b-0'>
                  <p className='text-xs text-center font-medium'>
                    PARAMETER TAMBAHAN YANG DIBUTUHKAN
                  </p>
                </div>
              </div>
              <div className='w-[200px] flex-shrink-0'>
                <div className='h-[100px] p-2 border border-black border-l-0 border-b-0'>
                  <p className='text-xs text-center font-medium'>SKOR NYERI</p>
                </div>
              </div>
              <div className='w-full min-w-0 overflow-x-auto'>
                <div className='flex min-w-max'>
                  {res.nyeri.map((item) => (
                    <div
                      key={`${item.jam}-${item.skor_nyeri}`}
                      className='w-[165px] flex-shrink-0'
                    >
                      <div className='p-2 border border-black border-b-0 border-l-0'>
                        <p className='text-[10px] text-center font-medium'>
                          {item.jam}
                        </p>
                      </div>
                      <div className='p-2 border border-black border-b-0 border-l-0'>
                        <p className='text-xs text-center font-medium'>
                          {item.skor_nyeri}
                        </p>
                      </div>
                      <div className='p-2 border border-black border-l-0 border-b-0'>
                        <p className='text-xs text-center font-medium'>
                          {item.hasil}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Fluid Intake Table */}
            <div className='flex'>
              <div className='w-[200px] flex-shrink-0'>
                <div className='h-[132px] p-2 border border-black'>
                  <p className='text-xs text-center font-medium'>MASUK</p>
                </div>
              </div>
              <div className='w-[200px] flex-shrink-0'>
                <div className='p-2 border border-black border-b-0 border-l-0'>
                  <p className='text-xs text-center'>Peroral/NGT</p>
                </div>
                <div className='p-2 border border-black border-b-0 border-l-0'>
                  <p className='text-xs text-center'>Parerental/Transfusi</p>
                </div>
                <div className='p-2 border border-black border-b-0 border-l-0'>
                  <p className='text-xs text-center'>Minum</p>
                </div>
                <div className='p-2 border border-black border-l-0'>
                  <p className='text-xs text-center'>Jumlah</p>
                </div>
              </div>
              <div className='w-full min-w-0 overflow-x-auto'>
                <div className='flex min-w-max'>
                  {res.monitoring_cairan.map((item, index) => (
                    <div
                      key={`intake-${index}`}
                      className='w-[165px] flex-shrink-0'
                    >
                      <div className='p-2 border border-black border-b-0 border-l-0'>
                        <p className='text-xs text-center'>{item.intake.ngt}</p>
                      </div>
                      <div className='p-2 border border-black border-b-0 border-l-0'>
                        <p className='text-xs text-center'>
                          {item.intake.infuse}
                        </p>
                      </div>
                      <div className='p-2 border border-black border-b-0 border-l-0'>
                        <p className='text-xs text-center'>
                          {item.intake.minum}
                        </p>
                      </div>
                      <div className='p-2 border border-black border-l-0'>
                        <p className='text-xs text-center'>
                          {item.intake.total}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Fluid Output Table */}
            <div className='flex'>
              <div className='w-[200px] flex-shrink-0'>
                <div className='h-[200px] p-2 border border-black border-t-0'>
                  <p className='text-xs text-center font-medium'>KELUAR</p>
                </div>
              </div>
              <div className='w-[200px] flex-shrink-0'>
                <div className='p-2 border border-black border-b-0 border-t-0 border-l-0'>
                  <p className='text-xs text-center font-medium'>Feses</p>
                </div>
                <div className='p-2 border border-black border-b-0 border-l-0'>
                  <p className='text-xs text-center font-medium'>Urine</p>
                </div>
                <div className='p-2 border border-black border-b-0 border-l-0'>
                  <p className='text-xs text-center font-medium'>Muntah/NGT</p>
                </div>
                <div className='p-2 border border-black border-l-0 border-b-0'>
                  <p className='text-xs text-center font-medium'>Drain/Darah</p>
                </div>
                <div className='p-2 border border-black border-l-0 border-b-0'>
                  <p className='text-xs text-center font-medium'>IWL</p>
                </div>
                <div className='p-2 border border-black border-l-0'>
                  <p className='text-xs text-center font-medium'>Jumlah</p>
                </div>
              </div>
              <div className='w-full min-w-0 overflow-x-auto'>
                <div className='flex min-w-max'>
                  {res.monitoring_cairan.map((item, index) => (
                    <div
                      key={`output-${index}`}
                      className='w-[165px] flex-shrink-0'
                    >
                      <div className='p-2 border border-black border-b-0 border-l-0 border-t-0'>
                        <p className='text-xs text-center font-medium'>
                          {item.output.feses}
                        </p>
                      </div>
                      <div className='p-2 border border-black border-b-0 border-l-0'>
                        <p className='text-xs text-center font-medium'>
                          {item.output.urine}
                        </p>
                      </div>
                      <div className='p-2 border border-black border-b-0 border-l-0'>
                        <p className='text-xs text-center font-medium'>
                          {item.output.ngt}
                        </p>
                      </div>
                      <div className='p-2 border border-black border-b-0 border-l-0'>
                        <p className='text-xs text-center font-medium'>
                          {item.output.drain}
                        </p>
                      </div>
                      <div className='p-2 border border-black border-b-0 border-l-0'>
                        <p className='text-xs text-center font-medium'>
                          {item.output.wsd}
                        </p>
                      </div>
                      <div className='p-2 border border-black border-l-0'>
                        <p className='text-xs text-center font-medium'>
                          {item.output.total}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Fluid Balance Table */}
            <div className='flex'>
              <div className='w-[200px] flex-shrink-0'>
                <div className='p-2 border border-black border-t-0'>
                  <p className='text-xs text-center font-medium'>
                    BALANCE CAIRAN
                  </p>
                </div>
              </div>
              <div className='w-[200px] flex-shrink-0'>
                <div className='p-2 border border-black border-t-0 border-l-0'>
                  <p className='text-xs text-center font-medium'>jumlah</p>
                </div>
              </div>
              <div className='w-full min-w-0 overflow-x-auto'>
                <div className='flex min-w-max'>
                  {res.monitoring_cairan.map((item, index) => (
                    <div
                      key={`balance-${index}`}
                      className='w-[165px] flex-shrink-0'
                    >
                      <div className='p-2 border border-black border-l-0 border-t-0'>
                        <p className='text-xs text-center font-medium'>
                          {item.output.total}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </LayoutBorderNo>
  )
}

export default ReportEwsDewasa
