/* eslint-disable @typescript-eslint/no-unused-vars */
import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report_header'
import { SimpleColumn } from '@/components/simple-column'
import { constants } from '@/utils/constants'

import {
  MonitoringTansfusiDarahModel,
  getMonitoringTransfusiDarah,
} from './monitoring-darah'

interface ReportMonitoringTransfusiDarahProps {
  isReport?: boolean
  noreg?: string
  norm?: string
  no?: string
}

const init: MonitoringTansfusiDarahModel[] = []

const getDateOnlySafe = (dateString: string | null | undefined): string => {
  if (!dateString) return '-'

  try {
    return dateString.includes('T') ? dateString.split('T')[0] : dateString
  } catch (error) {
    return dateString || '-'
  }
}

const ReportTransfusiDarah = ({
  isReport,
  noreg,
  no,
}: ReportMonitoringTransfusiDarahProps) => {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.monitoringTansfusiDarah, noreg!],
    queryFn: () => getMonitoringTransfusiDarah({ no_reg: noreg! }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : init
  console.log('res', res)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res.length == 0) return <EmptyPlaceholder message='data kosong' />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}
      <h1 className='text-center text-black font-semibold my-4'>
        MONITORING TRANSFUSI DARAH
      </h1>

      <div className='flex px-2'>
        <SimpleColumn name='No' className='text-xs flex-[0.5]' />
        <SimpleColumn name='Jenis Darah' className='text-xs flex-1' />
        <SimpleColumn name='Golongan Darah' className='text-xs flex-1' />
        <SimpleColumn name='No. Kantung' className='text-xs flex-1' />
        <SimpleColumn name='Reaksi' className='text-xs flex-1' />
        <SimpleColumn name='Tgl Kadaluarsa' className='text-xs flex-1' />
        <SimpleColumn isLast name='Perawat' className='text-xs flex-1 ' />
      </div>

      {res.length === 0 ? (
        <div className='px-2 py-4 text-center text-xs text-gray-500'>
          Tidak ada data
        </div>
      ) : (
        res.map((item, index) => (
          <div key={index} className='px-2 flex'>
            <SimpleColumn
              name={`${index + 1}`}
              className='text-xs flex-[0.5]'
            />
            <SimpleColumn name={item.jenis_darah} className='text-xs flex-1' />
            <SimpleColumn
              name={`${item.gol_darah}`}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={`${item.no_kantung}`}
              className='text-xs flex-1'
            />
            <div className='flex-1 text-xs border-r flex flex-col gap-2 text-center justify-center items-center p-2 border-y border-black border-l'>
              {item.reaksi && item.reaksi.length > 0 ? (
                item.reaksi.map((reaksi, idx) => (
                  <div key={idx} className='py-0.5'>
                    • {reaksi.reaksi} - {reaksi.keterangan}
                  </div>
                ))
              ) : (
                <div className='py-0.5'>Tidak ada reaksi</div>
              )}
            </div>
            <SimpleColumn
              name={`${getDateOnlySafe(item.tgl_kadaluarsa)}`}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={`${item.perawat.nama}`}
              isLast
              hasQR
              className='text-xs flex-1'
            />
          </div>
        ))
      )}

      <div className='h-[50px]' />
    </LayoutBorderNo>
  )
}
export default ReportTransfusiDarah
