import { DaftarObat, } from '@/models/pemberian_obat'
import type {
  Response,
} from '@/type'
import { post } from './api-2'
import { PemberianObat } from '@/models/obat_model'







const getDaftarObat = async (
  { no_reg }: { no_reg: string }
): Promise<Response<DaftarObat>> => {
  const response = await post(`/v1/report-instruksi-medis-farmakologi`, {
    no_reg, // ⬅️ langsung pakai shorthand
  })

  console.log("Response API:", response.data) // cek di console
  return response.data
}



const getDaftarObatV2 = async (
  { no_reg }: { no_reg: string }
): Promise<Response<PemberianObat[]>> => {
  const response = await post(`/v1/daftar-obat/get`, {
    no_reg, // ⬅️ langsung pakai shorthand
  })

  console.log("Response API:", response.data) // cek di console
  return response.data
}



export {
getDaftarObat,
getDaftarObatV2
}
