import type { LembarKonsulen, LembarKonsulV2, Response } from '@/type'

import { get } from './api'
import { get as getV2 } from './api-2'

const getLembarKonsulV2 = async ({
    noreg,
}: {
    noreg: string
}): Promise<Response<LembarKonsulV2>> => {
    const response = await get(`/v2/lembar-konsul/${noreg}`)

    return response.data
}

const getKonsulen= async ({
    noreg,
}: {
    noreg: string
}): Promise<Response<LembarKonsulen>> => {
    const response = await getV2(`/v2/view-all-alasan-konsul/${noreg}`)

    return response.data
}


export { getLembarKonsulV2, getKonsulen }
