
import type {
  Response,
} from '@/type'
import { post } from './api-2'




const getCaseRegister = async (
  { no_reg }: { no_reg: string }
): Promise<Response<CaseRegister[]>> => {
  const response = await post(`/v2/laporan-data-case-register-visite`, {
    no_reg, // ⬅️ langsung pakai shorthand
  })

  console.log("Response API:", response.data) // cek di console
  return response.data
}



export {getCaseRegister}



export interface CaseRegister {
    id:               number;
    insert_dttm:      string;
    tanggal:          string;
    noreg:            string;
    dokter:           string;
    visite:           string;
    nama_pemeriksaan: string;
    paraf:            string;
}


export class Convert {
    public static toCaseRegister(json: string): CaseRegister {
        return JSON.parse(json);
    }

    public static caseRegisterToJson(value: CaseRegister): string {
        return JSON.stringify(value);
    }
}
