import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { SimpleTTD } from '@/components/simple-ttd'
import { formatTanggalIndo, formatTanggalJam } from '@/helper/date'
import { PemberianObat } from '@/models/obat_model'
import { getDaftarObatV2 } from '@/services/daftar-obat-harian'
import { constants } from '@/utils/constants'

interface DaftarObatProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

const parseToArray = (value?: unknown): string[] => {
  if (!value) return []

  if (Array.isArray(value)) {
    return value
      .map(String)
      .map((v) => v.trim())
      .filter(Boolean)
  }

  if (typeof value !== 'string') return []

  const trimmed = value.trim()
  if (!trimmed || trimmed === 'null' || trimmed === 'undefined') return []

  return trimmed
    .split(',')
    .map((v) => v.trim())
    .filter(Boolean)
}

export function DaftarObatHarian({
  isReport = true,
  noreg = '',
}: DaftarObatProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.daftarObat, noreg],
    queryFn: () => getDaftarObatV2({ no_reg: noreg }),
  })

  const result =
    data?.response != null ? data?.response : ({} as PemberianObat[])

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-4'>
          DAFTAR OBAT HARIAN
        </h1>

        <div>
          {/* Header */}
          <div className='flex text-xs'>
            <SimpleColumn head name='No.' className='w-[50px]' />

            <SimpleColumn head name='Tanggal & Jam' className='w-[120px]' />

            <SimpleColumn
              head
              name='Obat Injeksi Dan Dosis'
              className='w-[200px]'
            />

            <SimpleColumn head name='Jam Diberi' className='flex-1' />

            <SimpleColumn head name='Frekuensi' className='w-[80px]' />

            <SimpleColumn head name='Nama Perawat' className='flex-1' />

            <SimpleColumn
              head
              name='Pasien/Keluarga'
              className='flex-1 border border-black text-center'
            />

            <SimpleColumn head name='Jam Diberi' className='flex-1' />

            <SimpleColumn head name='Sisa' className='w-[60px]' isLast />
          </div>
        </div>

        <>
          {result.map((item, index) => {
            // 1. Array nama obat (jika dipisah koma)
            const daftarObat = parseToArray(item.nama_obat)

            return daftarObat.map((namaObat, obatIndex) => {
              const listInsertDttm = parseToArray(item.daftar_insert_dttm)
              const listDiberi = parseToArray(item.jadwal_pemberian)
              const listUser = parseToArray(item.daftar_user)
              const listTtdFile = parseToArray(item.file_ttd)
              const listTtdNama = parseToArray(item.daftar_ttd_nama)
              const listSisaObat = parseToArray(item.daftar_sisa_obat)

              // Hitung berapa baris pemberian obat (misal: 1, 2, dst.)
              const maxRows = Math.max(
                listInsertDttm.length,
                listUser.length,
                listTtdNama.length,
                1,
              )

              const keyId = `${index}-${obatIndex}-${namaObat}`

              return (
                <div key={keyId} className='flex text-xs border-b'>
                  {/* No */}
                  <SimpleColumn
                    name={obatIndex === 0 ? (index + 1).toString() : ''}
                    className='w-[50px] border-r flex items-center justify-center p-1'
                  />

                  {/* Tanggal & Jam */}
                  <SimpleColumn
                    name={formatTanggalIndo(
                      parseToArray(item.daftar_insert_dttm)[0] || '',
                    )}
                    className='w-[120px] border-r flex items-center p-1'
                  />

                  {/* Obat Injeksi Dan Dosis */}
                  <SimpleColumn
                    name={`${namaObat} ${item.dosis ? `- ${item.dosis}` : ''}`}
                    className='w-[200px] border-r flex items-center p-1 font-medium'
                  />

                  {/* Bagian Sub-baris Pemberian Obat */}
                  <div className='flex-1 flex flex-col'>
                    {Array.from({ length: maxRows }, (_, pIndex) => {
                      const nomor = `${pIndex + 1}.`

                      const insertDttm = listInsertDttm[pIndex] || '-'
                      const jamDiberi = listDiberi[pIndex] || '-'
                      const userNama = listUser[pIndex] || '-'
                      const ttdFile = listTtdFile[pIndex] || ''
                      const ttdNama = listTtdNama[pIndex] || '-'
                      const sisaObat = listSisaObat[pIndex] || '-'

                      const isLastSubRow = pIndex === maxRows - 1

                      return (
                        <div
                          key={`${keyId}-row-${pIndex}`}
                          className={`flex flex-1 ${
                            !isLastSubRow ? 'border-b' : ''
                          }`}
                        >
                          {/* Jam Pemberian */}
                          <SimpleColumn
                            name={`${nomor} ${
                              insertDttm !== '-'
                                ? formatTanggalJam(insertDttm)
                                : '-'
                            }`}
                            className='flex-1 border-r p-1 flex items-center'
                          />

                          {/* Frekuensi */}
                          <SimpleColumn
                            name={`/ ${item.frekuensi || '-'} Jam`}
                            className='w-[80px] border-r p-1 flex items-center justify-center'
                          />

                          {/* Nama Perawat */}
                          <div className='flex-1 p-1 flex flex-col items-center justify-center'>
                            <SimpleColumn
                              name={userNama}
                              hasQR
                              className='w-full flex flex-col items-center justify-center'
                            />
                          </div>

                          {/* Pasien / Keluarga */}
                          <div className='flex-1 p-1 flex flex-col justify-between border border-black'>
                            <SimpleTTD
                              imageSrc={
                                ttdFile
                                  ? `${import.meta.env.VITE_BASE_API_URL_RME}/app/images/instruksi_farmakologi/${ttdFile}`
                                  : ''
                              }
                              name={`( ${ttdNama} )`}
                              className='w-full text-center'
                            />
                          </div>

                          {/* Jam Diberi */}
                          <SimpleColumn
                            name={` ${
                              jamDiberi !== '-'
                                ? formatTanggalJam(jamDiberi)
                                : '-'
                            }`}
                            className='flex-1 border-r p-1 flex items-center'
                          />

                          {/* Sisa */}
                          <SimpleColumn
                            name={` ${sisaObat}`}
                            className='w-[60px] p-1 flex items-center justify-center'
                            isLast
                          />
                        </div>
                      )
                    })}
                  </div>
                </div>
              )
            })
          })}
        </>
      </div>
    </LayoutBorderNo>
  )
}
