import { ReactNode } from 'react'
import QRCode from 'react-qr-code'

import { cn } from '@/lib/utils'

interface SimpleTTDProps {
  name?: string
  isLast?: boolean
  head?: boolean
  className?: string
  className2?: string
  hasQR?: boolean
  isChild?: ReactNode
  height?: string
  imageSrc?: string // 🔥 tambahan: untuk gambar
  imageAlt?: string // opsional alt text
}

export function SimpleTTD({
  name,
  head,
  isLast,
  className = 'flex-1',
  className2 = '',
  hasQR = false,
  isChild,
  height,
  imageSrc,
  imageAlt = 'image',
}: SimpleTTDProps) {
  if (isChild)
    return (
      <div
         className={cn(
          'flex flex-col gap-2 text-center justify-center items-center p-2 border-y border-black border-l w-full h-full',
          isLast && 'border-r',
          className,
          head && 'bg-gray-100',
        )}
      >
        {isChild}
      </div>
    )

  return (
    <div
      className={cn(
        'flex flex-col gap-2 text-center justify-center items-center p-2 border-y border-black border-l',
        isLast && 'border-r',
        className,
        head && 'bg-gray-100',
      )}
    >
      {/* ✅ Prioritas: tampilkan gambar kalau ada */}
      {imageSrc ? (
        <img
          src={imageSrc}
          alt={imageAlt}
          className={height ?? 'h-[50px] w-[50px] object-contain'}
        />
      ) : hasQR ? (
        <QRCode
          value={name!}
          className={height ?? 'h-[50px] w-[50px]'}
        />
      ) : null}

      {name && <p className={cn(className2)}>{name}</p>}
    </div>
  )
}
